import csv
import json
from decimal import Decimal, InvalidOperation, localcontext, MAX_EMAX, MIN_EMIN

totals = {}

with open("orders.csv", newline="", encoding="utf-8") as file:
    for row in csv.DictReader(file):
        if row.get("status") != "paid":
            continue
        try:
            amount = Decimal(row["amount"])
        except (InvalidOperation, TypeError, KeyError, ValueError):
            continue
        if not amount.is_finite():
            continue

        region = row["region"]
        previous = totals.get(region, Decimal(0))
        with localcontext() as context:
            context.prec = max(
                previous.adjusted(), amount.adjusted()
            ) - min(
                previous.as_tuple().exponent,
                amount.as_tuple().exponent,
            ) + 2
            context.Emax = MAX_EMAX
            context.Emin = MIN_EMIN
            totals[region] = previous + amount

print("{" + ",".join(
    json.dumps(region) + ":" + str(total)
    for region, total in totals.items()
) + "}")
